css:
[data-bz-section="value-cards"] .bz-block { padding-block: 0; }
[data-bz-section="value-cards"] [data-bz-node="vc-text"] p { max-width: 78ch; font-size: 14px; line-height: 1.7; color: var(--muted); margin: 0 0 40px; }
[data-bz-section="value-cards"] .bz-row[data-bz-node="vc-row"] { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 24px; }
[data-bz-section="value-cards"] .bz-row[data-bz-node="vc-row"]:has(> :nth-child(5)) { grid-template-columns: repeat(3, minmax(0, 1fr)); }
[data-bz-section="value-cards"] .bz-row[data-bz-node="vc-row"] > .bz-col { grid-column: auto; background: var(--card); border: 1px solid var(--line); border-radius: 4px; padding: 28px 26px 32px; }
[data-bz-section="value-cards"] [data-bz-node^="vc-title"] :is(h3, h4) { font: 700 14px / 1.3 var(--font-heading); letter-spacing: .06em; text-transform: uppercase; margin: 0 0 14px; }
[data-bz-section="value-cards"] [data-bz-node^="vc-body"] p { font-size: 13.5px; line-height: 1.65; color: var(--muted); margin: 0; }
@media (max-width: 1100px) { [data-bz-section="value-cards"] .bz-row[data-bz-node="vc-row"], [data-bz-section="value-cards"] .bz-row[data-bz-node="vc-row"]:has(> :nth-child(5)) { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 640px) { [data-bz-section="value-cards"] .bz-row[data-bz-node="vc-row"], [data-bz-section="value-cards"] .bz-row[data-bz-node="vc-row"]:has(> :nth-child(5)) { grid-template-columns: minmax(0, 1fr); } }
